(function(root){'use strict';const stack='"Kanji Unified Mincho", "Kanji Element Mincho", serif';root.KanjiCharacterFont={stack:()=>stack,weight:()=>400,mode:()=> 'unified'};document.documentElement.dataset.characterFont='unified';document.documentElement.style.setProperty('--character-font',stack);function repaint(){if(typeof root.refreshAvatarFont==='function')root.refreshAvatarFont();if(typeof root.drawFormation==='function'&&!document.getElementById('modal-formation')?.classList.contains('hidden'))root.drawFormation();if(typeof root.drawTutorial==='function')root.drawTutorial();}root.addEventListener('load',async()=>{try{await Promise.all([document.fonts.load('400 38px "Kanji Unified Mincho"','漢字'),document.fonts.load('400 38px "Kanji Element Mincho"','鿬鿫')]);repaint();}catch{}});})(window);
